import sqlite3
DB_PATH = 'ticketing.db'

def _sync_access(conn, marks, ticket_ids, to_session_id):
    # Revoke any outstanding share links for the moved tickets
    conn.execute(f'DELETE FROM ticket_shares WHERE ticket_id IN ({marks})', list(ticket_ids))
    # Grant ticket owners the attendee role on the destination session
    conn.execute(f"INSERT OR IGNORE INTO session_access (session_id, user_id, role) SELECT DISTINCT ?, owner_id, 'attendee' FROM tickets WHERE id IN ({marks})", [to_session_id, *ticket_ids])

def move_tickets_to_new_session(ticket_ids: list, from_session_id: int, to_session_id: int) -> dict:
    if not ticket_ids:
        return {'ok': False, 'error': 'no tickets given'}
    if not all((isinstance(t, int) and t > 0 for t in ticket_ids)):
        return {'ok': False, 'error': 'ticket ids must be positive integers'}
    if from_session_id == to_session_id:
        return {'ok': False, 'error': 'sessions are identical'}
    conn = sqlite3.connect(DB_PATH)
    try:
        src = conn.execute('SELECT event_id FROM sessions WHERE id = ?', (from_session_id,)).fetchone()
        dst = conn.execute('SELECT event_id, capacity, sold FROM sessions WHERE id = ?', (to_session_id,)).fetchone()
        if src is None or dst is None:
            return {'ok': False, 'error': 'session not found'}
        if src[0] != dst[0]:
            return {'ok': False, 'error': 'sessions belong to different events'}
        if dst[2] + len(ticket_ids) > dst[1]:
            return {'ok': False, 'error': 'destination session lacks capacity'}
        marks = ','.join(('?' for _ in ticket_ids))
        rows = conn.execute(f"SELECT id FROM tickets WHERE session_id = ? AND id IN ({marks}) AND status = 'valid'", [from_session_id, *ticket_ids]).fetchall()
        if len(rows) != len(ticket_ids):
            return {'ok': False, 'error': 'some tickets are not valid in the source session'}
        conn.execute(f'UPDATE tickets SET session_id = ?, seat = NULL WHERE id IN ({marks})', [to_session_id, *ticket_ids])
        conn.execute('UPDATE sessions SET sold = sold - ? WHERE id = ?', (len(ticket_ids), from_session_id))
        conn.execute('UPDATE sessions SET sold = sold + ? WHERE id = ?', (len(ticket_ids), to_session_id))
        _sync_access(conn, marks, ticket_ids, to_session_id)
        conn.commit()
    finally:
        conn.close()
    return {'ok': True, 'moved': len(ticket_ids), 'to_session_id': to_session_id}
